const dot=(x,y,rad=6,col=C.blue)=>`<circle cx="${x}" cy="${y}" r="${rad}" fill="${col}"/>`;
const arr=(x,y,xx,yy,col=C.blue,width=4)=>ln(x,y,xx,yy,col,width)+`<path d="M${xx-10} ${yy-6}L${xx} ${yy}L${xx-10} ${yy+6}" transform="rotate(${Math.atan2(yy-y,xx-x)*180/Math.PI} ${xx} ${yy})" fill="none" stroke="${col}" stroke-width="${width}"/>`;
