function climate(s,m){let o='';const data=[['DRY REJECTION','Outdoor dry-bulb',['Hot-day temperature','Equipment size + fan power'],C.orange],['EVAPORATIVE REJECTION','Outdoor wet-bulb',['Makeup water + treatment','Discharge / blowdown'],C.blue]];data.forEach(([a,b,c,col],i)=>{const x=m?27:70+i*610,y=m?55+i*304:83;o+=t(x,y,a,m?18:24,col);for(let n=0;n<3;n++){const cx=x+35+n*(m?106:130),cy=y+75;o+=`<circle cx="${cx}" cy="${cy}" r="25" fill="${C.surface}" stroke="${col}" stroke-width="2"/>`+path(`M${cx-15} ${cy}H${cx+15}M${cx} ${cy-15}V${cy+15}`,col,3);}o+=t(x,y+144,b,m?25:35,col)+tx(x,y+192,c,m?18:25,C.ink,'start',40);});o+=m?ln(26,328,364,328):ln(600,47,600,495);return done(o,'The dry-rejection site interface is outdoor dry-bulb temperature and hot-day equipment performance. Evaporative rejection is tied to wet-bulb conditions plus makeup water, treatment and discharge. Select the cooling system and site together; the IT loop alone does not determine water use.');}
